#!/usr/bin/env bash
set -euo pipefail
cd "$HOME/PFMP" || exit 1

DEPLOYMENT_ID="AKfycby6ykCxTxhUjq8FeKoBzgEMj6xzdrjXnBFgOt-1pAw1GfkaAigWMH7jj0EIg_BWpEkmxg"
LABEL="PFMP v1.0.0-dev.148-fix1"
FILE="apps-script/EUC_CONVENTION_PFMP_AdminWorkflowV144.gs"

STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP="backup_DEV148_avant_FIX1_${STAMP}"
mkdir -p "$BACKUP"
cp "$FILE" "$BACKUP/"

echo "" | base64 -d > /tmp/dev148_fix1_patch.py
python3 /tmp/dev148_fix1_patch.py

echo "=== CONTROLES DEV.148 FIX1 ==="
cp "$FILE" /tmp/EUC_ADMIN_WORKFLOW_V148_FIX1.js
node --check /tmp/EUC_ADMIN_WORKFLOW_V148_FIX1.js
grep -q "function EUC_PFMP_anneeDossierV148_" "$FILE"
grep -q "var anneeDossier=EUC_PFMP_anneeDossierV148_" "$FILE"

echo "OK : syntaxe valide."
echo "OK : détermination centralisée de l'année scolaire."

echo "=== PUSH ==="
clasp push -f

echo "=== VERSION ==="
clasp version "$LABEL"

echo "=== DEPLOIEMENT PRINCIPAL ==="
clasp deploy -i "$DEPLOYMENT_ID" -d "$LABEL"

echo "============================================================"
echo " DEV.148 FIX1 DEPLOYEE AVEC SUCCES"
echo "============================================================"
echo "✓ erreur 'annee is not defined' corrigée"
echo "✓ année scolaire déterminée depuis champ / numéro / date de début"
echo "✓ push + version + déploiement principal"
echo "============================================================"
